import{_ as i,o as a,c as t,a6 as s}from"./chunks/framework.DL_pga9_.js";const u=JSON.parse('{"title":"Native Module Artifacts","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/native_module_artifacts.md","filePath":"design/archive/native_module_artifacts.md","lastUpdated":1780030916000}'),l={name:"design/archive/native_module_artifacts.md"};function n(r,e,d,o,c,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="native-module-artifacts" tabindex="-1">Native Module Artifacts <a class="header-anchor" href="#native-module-artifacts" aria-label="Permalink to “Native Module Artifacts”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 5. Module-system-local order: 2.</p><p>Implementation status: initial implementation landed on the module artifact branch. Native descriptors are now first-class registry inputs for the type checker, STUPID, and ORGASM.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Represent native modules as first-class module artifacts so native functions, native opaque types, traits, and impl evidence can be imported with the same syntax and metadata path as source modules.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li><a href="./module_artifact_typechecker">Module Artifact And Typechecker Integration</a></li></ul><p>Unblocks:</p><ul><li>Native-backed standard library modules.</li><li><a href="./stdlib_modularization">Standard Library Modularization</a></li><li>More reliable <code>type T = native;</code> type checking.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li><code>NativeModuleDescriptor</code>.</li><li>Native module registration in <code>ModuleRegistry</code>.</li><li>NG-visible native signatures through <code>.ng</code> stubs or descriptor metadata.</li><li>Native opaque types via <code>type T = native;</code>.</li><li>Native functions imported with normal <code>import</code>.</li><li>Native-exported trait and impl evidence.</li><li>Descriptor/stub agreement checks.</li></ul><p>Out of scope:</p><ul><li><code>.ngo</code> bytecode persistence.</li><li>Splitting the standard library into final module layout.</li><li>Procedural native code generation.</li></ul><h2 id="core-model" tabindex="-1">Core Model <a class="header-anchor" href="#core-model" aria-label="Permalink to “Core Model”">​</a></h2><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NativeModuleDescriptor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Str moduleId;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Map</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Str, NGCallable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> functions;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TypeIndex typeIndex;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ModuleExportIndex exports;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ModuleTraitIndex traits;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ModuleImplIndex impls;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Str origin;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Str version;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requireSignatures </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>Rules:</p><ul><li>Native modules are <code>ModuleArtifact{.format = ModuleFormat::Native}</code>.</li><li><code>type T = native;</code> remains the NG-side opaque value declaration.</li><li>Native functions must have NG signatures available either from <code>.ng</code> stub modules or native descriptors.</li><li>Native modules can export opaque types, functions, traits, and impl evidence.</li><li>Native module impl evidence participates in duplicate impl diagnostics.</li><li>Descriptor registration publishes a shared <code>ModuleArtifact</code> and registers a runtime module.</li><li>If a source stub runtime module has already been loaded, descriptor registration augments it with native handlers instead of replacing NG-defined helper functions.</li><li>If no source stub exists, STUPID falls back to the native runtime module registered by the descriptor.</li><li>ORGASM treats imported native functions as external imports backed by VM native handlers.</li></ul><p>Recommended layout:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lib/std/prelude.ng</span></span>
<span class="line"><span>lib/std/imgui.ng</span></span>
<span class="line"><span>native/std/prelude      // registered C++ descriptor</span></span>
<span class="line"><span>native/std/imgui        // registered C++ descriptor</span></span></code></pre></div><h2 id="descriptor-and-stub-agreement" tabindex="-1">Descriptor And Stub Agreement <a class="header-anchor" href="#descriptor-and-stub-agreement" aria-label="Permalink to “Descriptor And Stub Agreement”">​</a></h2><p>If a native module has an NG stub, the checker should verify:</p><ul><li>Every exported native function in the stub exists in the descriptor.</li><li>Every descriptor function used by imports has a visible NG type.</li><li>Native opaque types in the stub match descriptor type names.</li><li>Exported trait/impl evidence in descriptor and stub do not conflict.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li>A native module can be imported with normal <code>import</code>.</li><li>A native-backed function has a checked NG signature and a C++ runtime handler.</li><li>A native opaque type can be exported and used by source modules.</li><li>Native-exported impl evidence participates in trait satisfaction.</li><li>Descriptor/stub mismatches produce deterministic diagnostics.</li></ul><h2 id="implemented-coverage" tabindex="-1">Implemented Coverage <a class="header-anchor" href="#implemented-coverage" aria-label="Permalink to “Implemented Coverage”">​</a></h2><ul><li><code>NativeModuleDescriptor</code> registration in <code>ModuleRegistry</code>.</li><li>Native descriptor metadata import in the type checker, including descriptor-only modules with no source file.</li><li>STUPID import fallback for native-only artifacts.</li><li>STUPID source-stub compatibility, including mixed NG helper functions plus native handlers.</li><li>ORGASM external native imports for descriptor-backed modules.</li><li>Native descriptors for <code>std.prelude</code> and <code>std.imgui</code>.</li></ul><h2 id="remaining-work" tabindex="-1">Remaining Work <a class="header-anchor" href="#remaining-work" aria-label="Permalink to “Remaining Work”">​</a></h2><ul><li>Persisted native artifact metadata for <code>.ngo</code> module loading.</li><li>Full duplicate trait impl diagnostics across native/source module boundaries.</li><li>Richer descriptor/stub agreement diagnostics for trait and impl evidence mismatches.</li></ul>`,31)])])}const m=i(l,[["render",n]]);export{u as __pageData,m as default};
